/**
 * InkOS Payments — RPC + DB row contracts (Sprint 13)
 *
 * Source of truth for the dual-stack payment system.
 *   • L1 — Dodo Payments (SaaS subscriptions, MoR-handled global tax). Existing.
 *   • L2 — Stripe Connect Express (in-studio marketplace, NEW from Sprint 13).
 *
 * EVERY RPC SIGNATURE LIVES HERE BEFORE DATO WRITES THE MIGRATION.
 * Param-name drift between TS and SQL is the #1 InkOS bug source (per inkos-lessons §1).
 *
 * Money is ALWAYS stored as `cents INT`. Never numeric. Never float.
 * Banker's rounding when splitting.
 *
 * Owner: inkos-payments-lead (.claude/agents/inkos-payments-lead.md)
 */

// =====================================================================
// PRIMITIVE TYPES
// =====================================================================

/** ISO 4217 lowercase currency code as used by Stripe. Lock the supported set. */
export type Currency = 'usd' | 'gbp' | 'eur' | 'aud' | 'cad';

/**
 * Money expressed as integer minor units (cents, pence, etc).
 * Branded so a raw `number` can't be passed where money is expected.
 */
export type CentsAmount = number & { readonly __brand: 'CentsAmount' };

/** Construct a CentsAmount with bounds checking. Negative amounts allowed for refunds/reversals. */
export function cents(value: number): CentsAmount {
  if (!Number.isInteger(value)) {
    throw new Error(`CentsAmount must be integer, got ${value}`);
  }
  return value as CentsAmount;
}

/**
 * Idempotency key carried in Stripe metadata for webhook reconciliation.
 * UUID v4 generated at call site; same key reused on retry of same logical operation.
 */
export type InkosIdempotencyKey = string & { readonly __brand: 'InkosIdempotencyKey' };

/** Webhook event source — used in `webhook_events.source` UNIQUE constraint. */
export type WebhookSource = 'dodo' | 'stripe';

// =====================================================================
// ENUMS — mirror SQL CHECK constraints
// =====================================================================

/** Stripe Connect Express account type. One per studio (mandatory) + optional one per artist. */
export type ConnectedAccountType = 'studio' | 'artist';

/** Connect onboarding lifecycle. Updated by `account.updated` webhook. */
export type ConnectedAccountOnboardingStatus =
  | 'pending'    // account created, KYC not started
  | 'active'     // charges_enabled && payouts_enabled
  | 'restricted' // partially complete; some capabilities disabled
  | 'rejected';  // permanently blocked by Stripe

/** Stripe charge lifecycle (mirrored from PaymentIntent status). */
export type StripeChargeStatus =
  | 'requires_payment_method'
  | 'requires_confirmation'
  | 'requires_action'
  | 'processing'
  | 'requires_capture'
  | 'canceled'
  | 'succeeded'
  | 'refunded'
  | 'partially_refunded';

/** Dispute lifecycle. */
export type StripeDisputeStatus =
  | 'warning_needs_response'
  | 'warning_under_review'
  | 'warning_closed'
  | 'needs_response'
  | 'under_review'
  | 'won'
  | 'lost'
  | 'charge_refunded';

/** Defense pack assembly + submission status. */
export type DisputeDefensePackStatus =
  | 'pending'    // BullMQ job not yet run
  | 'assembling' // job running, gathering documents
  | 'ready'      // bundle PDF generated, awaiting submission
  | 'submitted'  // sent to Stripe via /v1/disputes/:id
  | 'failed';    // assembly or submission errored

/** Commission split kind — distinguishes original split from reversal. */
export type CommissionSplitKind =
  | 'split'      // original 70/30 split on session settlement
  | 'reversal'   // reverses a prior split (refund, dispute lost)
  | 'adjustment' // manual correction (rare, audit-logged)
  | 'tip';       // tip-only transfer (separate row from base split)

/** Tax remittance ledger row status. */
export type TaxRemittanceStatus =
  | 'open'           // collected this period, not yet remitted
  | 'manual_review'  // Stripe Tax API failed or jurisdiction not supported
  | 'filed'          // remittance filed with tax authority
  | 'paid';          // payment cleared

/** 1099-NEC export source — Stripe-issued vs InkOS-internal calc. */
export type Nec1099Source = 'stripe' | 'inkos_internal';

// =====================================================================
// TABLE ROW TYPES — shape Dato's CREATE TABLE statements must produce
// =====================================================================

/**
 * `webhook_events` — first write of every webhook handler.
 * UNIQUE (source, event_id) drives idempotency.
 * `INSERT ... ON CONFLICT (source, event_id) DO NOTHING` returns 200 immediately on replay.
 */
export interface WebhookEventRow {
  id: string;                     // UUID
  source: WebhookSource;          // 'dodo' | 'stripe'
  event_id: string;               // provider's event id
  event_type: string;             // e.g. 'payment_intent.succeeded'
  payload: unknown;               // JSONB — raw webhook body
  signature_verified: boolean;    // result of HMAC check
  processed_at: string | null;    // timestamptz; null until handler completes
  error: string | null;           // last error message if retried
  retry_count: number;            // incremented by replay queue
  created_at: string;             // timestamptz
}

/**
 * `stripe_connected_accounts` — one per studio (mandatory) + optional one per artist.
 * Studio's account is the platform's destination for in-studio charges.
 * Artist accounts let artists receive direct payouts (bypassing studio float).
 */
export interface StripeConnectedAccountRow {
  id: string;                                            // UUID
  studio_id: string;                                     // FK
  account_id: string;                                    // Stripe acct_xxx
  type: ConnectedAccountType;                            // 'studio' | 'artist'
  artist_id: string | null;                              // FK, NULL when type='studio'
  onboarding_status: ConnectedAccountOnboardingStatus;
  capabilities: {
    charges_enabled: boolean;
    payouts_enabled: boolean;
    transfers: boolean;
    tax_reporting_us_1099_nec: boolean;
    [k: string]: boolean | undefined;
  };
  country: string;                                       // ISO 3166-1 alpha-2
  default_currency: Currency;
  restricted_reason: string | null;
  requirements_due_by: string | null;                    // timestamptz
  created_at: string;
  updated_at: string;
}

/**
 * `stripe_charges` — mirror of every PaymentIntent we initiate.
 * idempotency_key UNIQUE prevents duplicate writes on webhook replay.
 * Money in CentsAmount, currency separate (no implicit USD).
 */
export interface StripeChargeRow {
  id: string;
  studio_id: string;
  payment_intent_id: string;                  // pi_xxx
  charge_id: string | null;                   // ch_xxx (null until succeeded)
  transfer_id: string | null;                 // tr_xxx (null on pool-only charges)
  application_fee_id: string | null;          // fee_xxx
  status: StripeChargeStatus;
  currency: Currency;
  amount_cents: CentsAmount;                  // total client paid (incl tax + tip)
  tax_amount_cents: CentsAmount;              // recorded by Stripe Tax
  application_fee_cents: CentsAmount;         // studio's commission
  net_artist_cents: CentsAmount;              // amount_cents - tax - application_fee - tip (split base)
  tip_amount_cents: CentsAmount;              // tip routed separately, 100% to artist by default
  booking_id: string | null;
  project_id: string | null;
  session_id: string | null;
  client_id: string | null;
  deposit_drawdown_cents: CentsAmount;        // pool draw applied to this charge (0 if none)
  idempotency_key: InkosIdempotencyKey;       // UNIQUE
  presentment_currency: Currency | null;      // for cross-border FX
  presentment_amount_cents: CentsAmount | null;
  created_at: string;
}

/**
 * `stripe_disputes` — mirrors Stripe disputes; defense pack assembled async.
 */
export interface StripeDisputeRow {
  id: string;
  studio_id: string;
  dispute_id: string;                         // dp_xxx
  charge_id: string;                          // ch_xxx (FK to stripe_charges.charge_id)
  reason: string;                             // Stripe's reason code
  status: StripeDisputeStatus;
  amount_cents: CentsAmount;
  currency: Currency;
  evidence_due_by: string;                    // timestamptz — submit 24h before
  defense_pack_status: DisputeDefensePackStatus;
  defense_pack_url: string | null;            // signed Storage URL of bundle PDF
  submitted_at: string | null;
  resolved_at: string | null;
  resolved_amount_cents: CentsAmount | null;  // final clawback if lost
  created_at: string;
}

/**
 * `tax_remittance_ledger` — quarterly tax accumulator per studio per location per jurisdiction.
 * Reconciles to Stripe Tax reports within $0.01.
 */
export interface TaxRemittanceLedgerRow {
  id: string;
  studio_id: string;
  location_id: string;
  jurisdiction: string;                       // e.g. 'US-NY-NYC', 'GB', 'EU-DE'
  period: string;                             // e.g. '2026-Q2', '2026-04'
  amount_collected_cents: CentsAmount;
  amount_remitted_cents: CentsAmount;
  remittance_date: string | null;
  remittance_reference: string | null;        // confirmation # from tax authority
  status: TaxRemittanceStatus;
  created_at: string;
  updated_at: string;
}

/**
 * `commission_splits` — one row per artist payout per session settlement.
 * Reversals reference parent_split_id for refund/dispute proportional clawback.
 */
export interface CommissionSplitRow {
  id: string;
  studio_id: string;
  booking_id: string | null;
  session_id: string | null;
  artist_id: string;
  base_amount_cents: CentsAmount;             // pre-fee artist share
  commission_pct: number;                     // 0.00–100.00 (numeric in DB but bounded)
  tip_amount_cents: CentsAmount;              // separate row when kind='tip'
  applied_from_pool_cents: CentsAmount;       // pool drawdown in this split
  stripe_transfer_id: string | null;          // tr_xxx (null on pool-only splits)
  kind: CommissionSplitKind;
  parent_split_id: string | null;             // for reversals
  created_at: string;
}

/**
 * `dispute_defense_packs` — bundled evidence PDF + provenance trail.
 */
export interface DisputeDefensePackRow {
  id: string;
  dispute_id: string;
  signed_consent_url: string | null;
  photo_release_url: string | null;
  session_photos_urls: string[];
  chat_history_url: string | null;
  deposit_policy_text: string;
  receipt_url: string | null;
  bundle_pdf_url: string | null;
  generated_at: string;
}

/**
 * `nec_1099_exports` — annual 1099-NEC export per artist.
 * Stripe-issued (preferred) cross-checked against InkOS-internal calc from commission_splits.
 */
export interface Nec1099ExportRow {
  id: string;
  studio_id: string;
  year: number;
  artist_id: string;
  total_paid_cents: CentsAmount;
  federal_id_last4: string | null;
  state_id_last4: string | null;
  csv_url: string | null;
  pdf_url: string | null;
  source: Nec1099Source;                      // 'stripe' | 'inkos_internal'
  generated_at: string;
}

// =====================================================================
// RPC CONTRACTS — exact signatures Dato implements in SQL
// =====================================================================
// Each RPC has: name, args interface, return type.
// SQL function name MATCHES the constant string literal `RPC.<NAME>`.
// SQL parameter names MATCH camelCase → snake_case translation:
//   args.studioId → p_studio_id (Postgres convention).
// Drift between this file and SQL is a P0 bug — Sage scans match.

export const RPC = {
  WEBHOOK_EVENT_INSERT: 'webhook_event_insert',
  STRIPE_CONNECTED_ACCOUNT_CREATE: 'stripe_connected_account_create',
  STRIPE_CONNECTED_ACCOUNT_UPDATE_FROM_WEBHOOK: 'stripe_connected_account_update_from_webhook',
  STRIPE_CHARGE_RECORD: 'stripe_charge_record',
  STRIPE_CHARGE_UPDATE_STATUS_FROM_WEBHOOK: 'stripe_charge_update_status_from_webhook',
  COMMISSION_SPLIT_RECORD: 'commission_split_record',
  COMMISSION_SPLIT_REVERSE: 'commission_split_reverse',
  STRIPE_DISPUTE_RECORD: 'stripe_dispute_record',
  STRIPE_DISPUTE_UPDATE_STATUS_FROM_WEBHOOK: 'stripe_dispute_update_status_from_webhook',
  DISPUTE_DEFENSE_PACK_RECORD: 'dispute_defense_pack_record',
  TAX_REMITTANCE_ACCRUE: 'tax_remittance_accrue',
  TAX_REMITTANCE_FILE: 'tax_remittance_file',
  NEC_1099_EXPORT_RECORD: 'nec_1099_export_record',
} as const;

// ---------- webhook_event_insert ----------

/** Idempotently insert a webhook event. Returns true if newly inserted, false if conflict (replay). */
export interface WebhookEventInsertArgs {
  source: WebhookSource;
  eventId: string;
  eventType: string;
  payload: unknown;
  signatureVerified: boolean;
}
export type WebhookEventInsertResult = { inserted: boolean; id: string | null };

// ---------- stripe_connected_account_create ----------

export interface StripeConnectedAccountCreateArgs {
  studioId: string;
  type: ConnectedAccountType;
  artistId: string | null;
  accountId: string;                 // Stripe acct_xxx
  country: string;                   // ISO 3166-1 alpha-2
  defaultCurrency: Currency;
}
export type StripeConnectedAccountCreateResult = { id: string };

// ---------- stripe_connected_account_update_from_webhook ----------

/** Updates onboarding_status + capabilities on `account.updated` webhook. Idempotent. */
export interface StripeConnectedAccountUpdateFromWebhookArgs {
  accountId: string;
  onboardingStatus: ConnectedAccountOnboardingStatus;
  capabilities: StripeConnectedAccountRow['capabilities'];
  country: string;
  defaultCurrency: Currency;
  restrictedReason: string | null;
  requirementsDueBy: string | null;
}
export type StripeConnectedAccountUpdateFromWebhookResult = { id: string; status: ConnectedAccountOnboardingStatus };

// ---------- stripe_charge_record ----------

/**
 * Insert a stripe_charges row at PaymentIntent creation time.
 * Idempotent on idempotency_key — same key returns existing row id.
 */
export interface StripeChargeRecordArgs {
  studioId: string;
  paymentIntentId: string;
  status: StripeChargeStatus;
  currency: Currency;
  amountCents: CentsAmount;
  taxAmountCents: CentsAmount;
  applicationFeeCents: CentsAmount;
  netArtistCents: CentsAmount;
  tipAmountCents: CentsAmount;
  bookingId: string | null;
  projectId: string | null;
  sessionId: string | null;
  clientId: string | null;
  depositDrawdownCents: CentsAmount;
  idempotencyKey: InkosIdempotencyKey;
  presentmentCurrency: Currency | null;
  presentmentAmountCents: CentsAmount | null;
}
export type StripeChargeRecordResult = { id: string; created: boolean };

// ---------- stripe_charge_update_status_from_webhook ----------

export interface StripeChargeUpdateStatusFromWebhookArgs {
  paymentIntentId: string;
  status: StripeChargeStatus;
  chargeId: string | null;
  transferId: string | null;
  applicationFeeId: string | null;
}
export type StripeChargeUpdateStatusFromWebhookResult = { id: string; status: StripeChargeStatus };

// ---------- commission_split_record ----------

export interface CommissionSplitRecordArgs {
  studioId: string;
  bookingId: string | null;
  sessionId: string | null;
  artistId: string;
  baseAmountCents: CentsAmount;
  commissionPct: number;
  tipAmountCents: CentsAmount;
  appliedFromPoolCents: CentsAmount;
  stripeTransferId: string | null;
  kind: CommissionSplitKind;
}
export type CommissionSplitRecordResult = { id: string };

// ---------- commission_split_reverse ----------

/**
 * Reverses a prior split (refund, dispute lost).
 * Inserts a new row with kind='reversal' and parent_split_id = original.
 * Returns the reversal row id.
 */
export interface CommissionSplitReverseArgs {
  parentSplitId: string;
  reverseAmountCents: CentsAmount;          // can be partial
  reverseTipCents: CentsAmount;
  reverseStripeTransferId: string | null;
}
export type CommissionSplitReverseResult = { id: string };

// ---------- stripe_dispute_record ----------

export interface StripeDisputeRecordArgs {
  studioId: string;
  disputeId: string;
  chargeId: string;
  reason: string;
  status: StripeDisputeStatus;
  amountCents: CentsAmount;
  currency: Currency;
  evidenceDueBy: string;
}
export type StripeDisputeRecordResult = { id: string };

// ---------- stripe_dispute_update_status_from_webhook ----------

export interface StripeDisputeUpdateStatusFromWebhookArgs {
  disputeId: string;
  status: StripeDisputeStatus;
  resolvedAt: string | null;
  resolvedAmountCents: CentsAmount | null;
}
export type StripeDisputeUpdateStatusFromWebhookResult = { id: string; status: StripeDisputeStatus };

// ---------- dispute_defense_pack_record ----------

export interface DisputeDefensePackRecordArgs {
  disputeId: string;
  signedConsentUrl: string | null;
  photoReleaseUrl: string | null;
  sessionPhotosUrls: string[];
  chatHistoryUrl: string | null;
  depositPolicyText: string;
  receiptUrl: string | null;
  bundlePdfUrl: string | null;
}
export type DisputeDefensePackRecordResult = { id: string };

// ---------- tax_remittance_accrue ----------

/**
 * Increments tax_remittance_ledger.amount_collected_cents for the matching
 * (studio, location, jurisdiction, period). Creates row if not exists.
 */
export interface TaxRemittanceAccrueArgs {
  studioId: string;
  locationId: string;
  jurisdiction: string;
  period: string;
  amountCollectedCents: CentsAmount;
}
export type TaxRemittanceAccrueResult = { id: string; new_total_cents: CentsAmount };

// ---------- tax_remittance_file ----------

export interface TaxRemittanceFileArgs {
  ledgerId: string;
  amountRemittedCents: CentsAmount;
  remittanceDate: string;
  remittanceReference: string;
}
export type TaxRemittanceFileResult = { id: string; status: TaxRemittanceStatus };

// ---------- nec_1099_export_record ----------

export interface Nec1099ExportRecordArgs {
  studioId: string;
  year: number;
  artistId: string;
  totalPaidCents: CentsAmount;
  federalIdLast4: string | null;
  stateIdLast4: string | null;
  csvUrl: string | null;
  pdfUrl: string | null;
  source: Nec1099Source;
}
export type Nec1099ExportRecordResult = { id: string };

// =====================================================================
// PRESET SPLIT PERCENTAGES (locked defaults — overridable per studio)
// =====================================================================

export const DEFAULT_COMMISSION_PCT = {
  RESIDENT_ESTABLISHED: 70,    // 70/30 in artist's favor
  RESIDENT_NEW: 60,            // 60/40
  RESIDENT_FULL_SUPPORT: 50,   // 50/50 when shop covers everything
  GUEST: 80,                   // 80/20 in guest's favor
  APPRENTICE: 50,              // 50/50 ramp
  BOOTH_RENTER: 100,           // booth renter keeps everything (rent invoiced separately)
} as const;

// =====================================================================
// INVARIANTS — Sage scans verify these hold across the codebase
// =====================================================================

/**
 * INVARIANT 1: All money is CentsAmount. Never `number` for money.
 * INVARIANT 2: Every Stripe call carries `metadata.inkos_idempotency_key`.
 * INVARIANT 3: Every webhook handler's first write is webhook_event_insert.
 * INVARIANT 4: `application_fee_amount` is set on every PaymentIntent (never undefined).
 * INVARIANT 5: Refunds always pass `reverse_transfer: true` AND `refund_application_fee: true`.
 * INVARIANT 6: `subscriptions` and `stripe_charges` are webhook-only writes from app code.
 * INVARIANT 7: Dodo (L1) and Stripe (L2) abstractions never share a module.
 * INVARIANT 8: Banker's rounding when computing splits to avoid systematic bias.
 */

